SELECT ROUND(100.0 * SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) / COUNT(*), 2) AS percentage
FROM Player p
JOIN (
  SELECT player_fifa_api_id, preferred_foot
  FROM Player_Attributes pa1
  WHERE date = (
    SELECT MAX(date) FROM Player_Attributes pa2 WHERE pa2.player_fifa_api_id = pa1.player_fifa_api_id
  )
) pa ON pa.player_fifa_api_id = p.player_fifa_api_id
WHERE substr(p.birthday,1,4) BETWEEN '1987' AND '1992';

